from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.conf import settings
from .models import CommercialLead
from .serializers import LeadSerializer

class CommercialLeadDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, lead_id):
        try:
            # Enforce tenant isolation scoping
            lead = CommercialLead.objects.get(id=lead_id, organization=request.user.organization)
        except CommercialLead.DoesNotExist:
            return Response({'error': 'Lead not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

        response = Response(LeadSerializer(lead).data)
        origin = request.headers.get('Origin')
        if origin in settings.CORS_ALLOWED_ORIGINS:
            response['Access-Control-Allow-Origin'] = origin
            response['Access-Control-Allow-Credentials'] = 'true'
        return response
